(async () => {
  const results = [];
  const wait = () => new Promise(resolve => setTimeout(resolve, 250));
  function assert(value, label) { results.push({ label, passed: !!value }); }
  const set = value => chrome.storage.local.set({ 'sisStudio.ui.v1': { enabled: true, theme: 'light', compact: false, ...value } });
  await wait();
  const app = globalThis.__sisStudioUI;
  const test = globalThis.studioTest;
  const control = document.querySelector('#sis-studio-controls').shadowRoot;
  assert(document.querySelectorAll('.studio-stat').length === 4, 'Real DOM creates four data-backed dashboard cards');
  assert([...document.querySelectorAll('.studio-stat-value')].map(e => e.textContent).join('|') === 'Fall 2026|2|7|60%', 'Summary arithmetic and lowest session percentage');
  assert(document.querySelectorAll('[data-studio-session]').length === 3, 'Separate lecture and lab labels');
  assert(document.querySelector('#bar_1-Lab .progress-bar').getAttribute('aria-valuenow') === '60', 'Screen readers receive the final attendance value');
  assert(!document.querySelector('.layout-table').hasAttribute('data-studio-table'), 'Layout tables are untouched');
  test.rows[0].dispatchEvent(new KeyboardEvent('keydown', { key: 'Enter', bubbles: true }));
  assert(test.clicks() === 1, 'Keyboard activation preserves original course click handler');
  document.querySelector('.studio-stat-action').click();
  assert(test.clicks() === 2, 'Lowest-attendance action opens the existing course handler');
  assert([...document.querySelectorAll('.studio-stat-note')].at(-1).textContent === 'TST101 · Lab', 'Lowest-attendance summary identifies the course and session');
  const search = document.querySelector('.studio-search');
  search.value = 'alpha'; search.dispatchEvent(new Event('input', { bubbles: true }));
  assert(document.querySelectorAll('[data-studio-filtered]').length === 1, 'Search filters without deleting rows');
  search.value = 'no matches'; search.dispatchEvent(new Event('input', { bubbles: true }));
  assert(!document.querySelector('.studio-search-empty').hidden, 'Search has an accessible empty state');
  await set({ enabled: false });
  assert(test.content.innerHTML === test.originalHTML, 'OFF restores exact original content HTML');
  assert(document.querySelector('.is-course-row') === test.rows[0], 'Original row identity survives disable');
  assert(!document.body.classList.contains('sis-studio-enabled') && !document.body.hasAttribute('data-sis-studio-theme'), 'OFF removes theme attributes and styling');
  assert(document.querySelectorAll('[data-sis-studio-owned="feature"]').length === 0, 'OFF removes all enhancement components');
  assert(!!document.querySelector('#sis-studio-controls'), 'OFF retains the re-enable control');
  await set({ theme: 'dark', compact: true });
  assert(document.body.dataset.sisStudioTheme === 'dark', 'Dark theme applied');
  assert(getComputedStyle(document.body).backgroundColor === 'rgb(11, 11, 13)', 'Dark theme uses a neutral near-black background');
  const hero = document.querySelector('.sis-bc-hero');
  assert(getComputedStyle(hero).backgroundImage === 'none' && getComputedStyle(hero).borderRadius === '10px', 'Late native important gradient cannot override card styling');
  assert(getComputedStyle(hero.querySelector('.sis-bc-print')).backgroundColor === 'rgb(27, 27, 30)', 'Student-card actions use the dark surface instead of white pills');
  assert(!control.querySelector('.dot'), 'Settings launcher has no status dot');
  assert(getComputedStyle(document.body).getPropertyValue('--sis-cell-y').trim() === '8px', 'Compact table token applied');
  const field = document.querySelector('[name=test-field]');
  assert(field.value === 'unchanged', 'Existing form value preserved');
  const select = document.querySelector('#test-select'); select.value = 'b';
  document.querySelector('#test-form').requestSubmit();
  assert(test.submits() === 1 && select.value === 'b', 'Form submit listener and select remain functional');
  for (let i = 0; i < 3; i++) { await set({ enabled: false }); await set({ theme: 'dark' }); }
  assert(document.querySelectorAll('.studio-overview').length === 1 && document.querySelectorAll('#sis-studio-controls').length === 1, 'Repeated toggles do not duplicate UI');
  const activeSearch = document.querySelector('.studio-search');
  activeSearch.value = 'beta'; activeSearch.dispatchEvent(new Event('input', { bubbles: true })); activeSearch.focus();
  document.querySelector('#bar_1-Class .progress-bar').textContent = '45%';
  await wait();
  assert([...document.querySelectorAll('.studio-stat-value')].at(-1).textContent === '45%', 'Observer refreshes after original attendance data changes');
  assert(document.querySelector('.studio-search').value === 'beta' && document.activeElement === document.querySelector('.studio-search') && document.querySelectorAll('[data-studio-filtered]').length === 1, 'Live updates preserve course search, filtering and keyboard focus');
  const replacement = test.content.cloneNode(true);
  replacement.querySelectorAll('[data-sis-studio-owned]').forEach(e => e.remove());
  test.content.replaceWith(replacement);
  await wait();
  assert(document.querySelectorAll('.studio-overview').length === 1, 'Content replacement reinitializes without duplicates');
  const fixture = document.createElement('div');
  const block = (semester, grade, cgpa) => `<div class="single_result_container"><div class="sis-result-meta"><table class="tbl_one"><tr><td>Semester: ${semester}</td></tr></table></div><table class="sis-result-grid"><tr><td>Course</td><td>Title</td><td>Credit</td><td>Marks</td><td>Grade</td><td>Points</td></tr><tr><td>TEST</td><td>Synthetic</td><td>3</td><td>0</td><td>${grade}</td><td>0</td></tr></table><div class="sis-result-summary"><table class="tbl_one"><tr><td>CGPA: ${cgpa}</td></tr></table></div></div>`;
  fixture.innerHTML = block('Spring 2026', 'A', '3.25') + block('Fall 2026', '-', '0.00');
  const parsed = app.parsers.results(fixture);
  assert(parsed[0].cgpa === 3.25 && parsed[1].cgpa === null, 'Ungraded zero CGPA is excluded');
  fixture.innerHTML = block('Fall 2026', 'F', '0.00');
  assert(app.parsers.results(fixture)[0].cgpa === 0, 'Published zero CGPA is retained when grades are present');
  fixture.innerHTML = '<div class="sis-dash-att"><div id="bar_3-Class" class="only_class_attendance"><div class="progress-bar" aria-valuemax="1">0%</div></div></div>';
  assert(app.parsers.courseAttendance(fixture).length === 0, 'Native animation placeholder is not treated as academic attendance');
  fixture.querySelector('.progress-bar').classList.add('bg-success');
  assert(app.parsers.courseAttendance(fixture)[0].value === 0, 'A completed genuine zero attendance is preserved');
  control.querySelector('.launch').click();
  assert(!control.querySelector('#panel').hidden, 'Settings open');
  control.querySelector('#enabled').dispatchEvent(new KeyboardEvent('keydown', { key: 'Escape', bubbles: true }));
  assert(control.querySelector('#panel').hidden && control.activeElement === control.querySelector('.launch'), 'Escape closes settings and restores focus');
  await set({ theme: 'system' });
  assert(document.body.dataset.sisStudioTheme === (matchMedia('(prefers-color-scheme: dark)').matches ? 'dark' : 'light'), 'System theme follows OS preference');
  app.destroy();
  assert(!document.querySelector('#sis-studio-controls') && !document.body.classList.contains('sis-studio-enabled'), 'Destroy removes UI and restores theme');
  const login = document.createElement('button'); login.id = 'LoginSubmit'; document.body.append(login);
  assert(!app.adapter.authenticated(), 'Login pages are excluded');
  globalThis.studioTestResults = results;
  document.querySelector('#test-output').textContent = results.map(result => `${result.passed ? 'PASS' : 'FAIL'} ${result.label}`).join('\n');
})().catch(error => { document.querySelector('#test-output').textContent = error.stack; globalThis.studioTestError = error.message; });
